query:
query DrugRecord($drugId: String!) {
  drug(chemblId: $drugId) {
    id name drugType description maximumClinicalStage
    tradeNames { label source }
    parentMolecule { id name maximumClinicalStage drugWarnings { id warningType toxicityClass country year description efoTerm efoId efoIdForWarningClass chemblIds references { id source url } } }
    childMolecules { id name maximumClinicalStage drugWarnings { id warningType toxicityClass country year description efoTerm efoId efoIdForWarningClass chemblIds references { id source url } } }
    drugWarnings { id warningType toxicityClass country year description efoTerm efoId efoIdForWarningClass chemblIds references { id source url } }
    mechanismsOfAction { rows { actionType mechanismOfAction targets { id approvedSymbol } } }
    indications {
      count
      rows {
        maxClinicalStage
        disease { id name }
        clinicalReports { id type clinicalStage source url year trialOverallStatus trialWhyStopped trialStopReasonCategories }
      }
    }
  }
}
